css:
:scope{display:block;width:100%}
.pw{background:#01111D;color:#EDE6D8;font-family:var(--os-font-body)}
.pw__in{box-sizing:content-box;max-width:1200px;margin:0 auto;padding:104px 32px 112px;display:flex;flex-wrap:wrap;gap:80px;align-items:flex-start}
.pw__cv{flex:1 1 300px;display:flex;justify-content:center}
.pw__img{width:320px;max-width:100%;line-height:0;box-shadow:0 30px 60px rgba(0,0,0,.55)}
.pw__img img{display:block;width:100%;height:auto}
.pw__ph{width:300px;height:450px;max-width:100%;box-sizing:border-box;border:1px solid #7B868066;box-shadow:0 30px 60px rgba(0,0,0,.55);display:flex;flex-direction:column;align-items:center;justify-content:space-between;padding:64px 20px 36px}
.pw__phw{font-family:var(--os-font-label);font-size:calc(var(--os-type-eyebrow-font-size) * 1.833);letter-spacing:.32em}
.pw__phs{font-family:var(--os-font-label);font-size:var(--os-type-eyebrow-font-size);letter-spacing:.3em;color:#BBAFA3}
.pw__tx{flex:999 1 520px;min-width:0}
.pw__kicker{margin:0;font-family:var(--os-font-label);font-weight:400;font-size:var(--os-type-eyebrow-font-size);letter-spacing:.32em;text-transform:uppercase;color:#BBAFA3}
.pw__rule{width:64px;height:1px;background:#C6A15B;margin:28px 0 32px}
.pw__h{margin:0;font-family:var(--os-font-heading);font-weight:500;font-size:var(--os-type-h1-font-size);line-height:var(--os-type-h1-line-height)}
.pw__lead{margin:24px 0 0;font-size:var(--os-type-body-font-size);line-height:var(--os-type-body-line-height);max-width:32em}
.pw__fmt{margin-top:32px;border-top:1px solid #7B868066;padding-top:28px}
.pw__lead+.pw__fmt{margin-top:48px}
.pw__row{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:baseline;gap:12px}
.pw__fn{margin:0;font-family:var(--os-font-label);font-weight:400;font-size:var(--os-type-eyebrow-font-size);letter-spacing:.3em;text-transform:uppercase;color:#EDE6D8}
.pw__fp{font-family:var(--os-font-label);font-size:var(--os-type-eyebrow-font-size);letter-spacing:.2em;text-transform:uppercase;color:#BBAFA3}
.pw__btns{display:flex;flex-wrap:wrap;gap:12px;margin-top:20px}
.pw__btn{display:inline-block;font-family:var(--os-font-label);font-weight:400;font-size:var(--os-type-eyebrow-font-size);letter-spacing:.2em;text-transform:uppercase;text-decoration:none;line-height:var(--os-type-eyebrow-line-height);color:#EDE6D8;border:1px solid #BBAFA3;padding:15px 21px}
.pw__btn--p{background:#8C5B46;border-color:#8C5B46;padding:16px 22px}
.pw__btn:focus-visible{outline:2px solid #EDE6D8;outline-offset:3px}
.pw__note{margin:14px 0 0;font-size:var(--os-type-body-font-size);line-height:var(--os-type-body-line-height);color:#BBAFA3}
@media (max-width:767px){.pw__in{padding:48px 20px 64px;gap:40px}
.pw__img{width:240px}
.pw__kicker{letter-spacing:.24em}
.pw__rule{margin:20px 0 24px}
.pw__btns{flex-direction:column}
.pw__btn{text-align:center}
.pw__tx{flex-basis:100%}}
